CREATE TABLE "app_devices" ("id" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "gym_id" TEXT NOT NULL REFERENCES gyms (id), "device_name" TEXT NOT NULL, "platform" TEXT NOT NULL, "last_seen_at" INTEGER NULL, "revoked_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "app_settings" ("gym_id" TEXT NOT NULL REFERENCES gyms (id), "key" TEXT NOT NULL, "value" TEXT NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("gym_id", "key"));
CREATE TABLE "audit_logs" ("id" TEXT NOT NULL, "gym_id" TEXT NOT NULL, "actor_id" TEXT NULL, "action" TEXT NOT NULL, "entity_table" TEXT NULL, "entity_id" TEXT NULL, "reason" TEXT NULL, "details_json" TEXT NOT NULL DEFAULT '{}', "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "gym_owners" ("id" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "gym_id" TEXT NOT NULL REFERENCES gyms (id), "display_name" TEXT NOT NULL, "email" TEXT NOT NULL, "password_hash" TEXT NOT NULL, "recovery_hash" TEXT NOT NULL, "failed_attempts" INTEGER NOT NULL DEFAULT 0, "locked_until" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("email"));
CREATE TABLE "gyms" ("id" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "name" TEXT NOT NULL, "logo_path" TEXT NULL, "address" TEXT NOT NULL DEFAULT '', "contact_number" TEXT NOT NULL DEFAULT '', "timezone" TEXT NOT NULL DEFAULT 'Asia/Kolkata', "currency" TEXT NOT NULL DEFAULT 'INR', "upi_id" TEXT NULL, "upi_payee_name" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "sync_operations" ("id" TEXT NOT NULL, "gym_id" TEXT NOT NULL, "entity_table" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "operation" TEXT NOT NULL, "payload_json" TEXT NOT NULL, "base_version" INTEGER NOT NULL DEFAULT 0, "idempotency_key" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "attempt_count" INTEGER NOT NULL DEFAULT 0, "last_error" TEXT NULL, "created_at" INTEGER NOT NULL, "synced_at" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("idempotency_key"));
CREATE INDEX idx_audit_gym_created ON audit_logs (gym_id, created_at);
CREATE INDEX idx_sync_ops_status ON sync_operations (status, created_at);